import { WindowLocationEvaluatorMessage, WindowLocationEvaluatorResponse } from 'manara-extension-types';

const ERROR_REGEX = /\?error=(.+)/;
const AUTH_CODE_REGEX = /\?code=([\w/-]+)/

const CALLBACK_HOST = "manara.tech";

const windowLocationEvaluatorListener = (msg: WindowLocationEvaluatorMessage, sender: chrome.runtime.MessageSender, sendResponse: (response: WindowLocationEvaluatorResponse) => void) => {
  console.log('[content.js]. Message received', msg);

  sendResponse({ location: window.location});
}

/**
 * Fired when a message is sent from either an extension process or a content script.
 */
 chrome.runtime.onMessage.addListener(windowLocationEvaluatorListener);


 if (window.location.host === CALLBACK_HOST) {
  console.log("FOUND MANARA CALLBACK")
  const url = window.location.href;
  if (url.match(ERROR_REGEX)) {
    chrome.tabs.getCurrent((tab) => {
      if (tab?.id == null) return;
      chrome.tabs.remove(tab.id, () => { });
    });
    // TODO set error state for rendering to extension
  } else {
    
    const parsedCode = url.match(AUTH_CODE_REGEX);

    // Found auth code, get acccess token and respond
    if (parsedCode && parsedCode.length > 1 && parsedCode[1]) {
      console.log("FOUND PARSED CODE");
      chrome.storage.local.set({
        'githubAuth': {
          authCode: parsedCode[1]
        }
      }, () => {
        console.log("Set github");
      });
    } 
  }
} 